style.html:
` when the viewer's display_mode preference
 *     is an explicit light or dark choice; system omits it so the OS drives resolution.
 *     The `html[data-color-scheme=...]` rules below apply on those pages.
 */
:root {
  color-scheme: light dark;
  --invert-in-dark-mode: 0;
  --blend-in-dark-mode: normal;
  --color-bg-neutral-primary: #ffffff;
  --color-bg-neutral-primary: light-dark(#ffffff, #171717);
  --color-bg-neutral-secondary: #f2f2f2;
  --color-bg-neutral-secondary: light-dark(#f2f2f2, #242424);
  --color-bg-neutral-tertiary: #f9f9f9;
  --color-bg-neutral-tertiary: light-dark(#f9f9f9, #1f1f1f);
  --color-bg-neutral-quaternary: #242424;
  --color-bg-neutral-quaternary: light-dark(#242424, #d2d2d2);
  /* Surfaces that float above the page: tooltips, popovers, menus, dialogs, side panels.
   * In dark mode these need to read as raised, so they sit a step lighter than
   * `--color-bg-neutral-primary` rather than blending into it. In light mode the shadow
   * already carries elevation, so the value matches the page. */
  --color-bg-neutral-elevated: #ffffff;
  --color-bg-neutral-elevated: light-dark(#ffffff, #1c1c1c);
  /* Floating UI on an already-elevated host (responses sidebar, etc.). One step above
   * `--color-bg-neutral-elevated` in dark mode so menus and cards do not blend in. */
  --color-bg-neutral-elevated-stacked: #ffffff;
  --color-bg-neutral-elevated-stacked: light-dark(#ffffff, #2b2b2b);
  /* The elevated surface for floating UI that is deliberately inverted against the page in
   * light mode (tooltips, toasts). Dark in BOTH schemes, so text on it must be pinned light
   * (`foreground.neutral.quaternary`, or `Detail`'s `neutral.quaternary`) rather than taken
   * from a flipping token, which would go near-black in dark mode and disappear. */
  --color-bg-neutral-elevated-inverted: #242424;
  --color-bg-neutral-elevated-inverted: light-dark(#242424, #1c1c1c);
  /* Inverted surface for the BRAND button. The light values are the legacy
   * `baseColor.fill.dark` / `.darker` grayscales, not palette constants, so that
   * light mode renders exactly as it did before dark mode support. */
  --color-bg-brand-primary: #191919;
  --color-bg-brand-primary: light-dark(#191919, #ffffff);
  --color-bg-brand-primary-hover: #080808;
  --color-bg-brand-primary-hover: light-dark(#080808, #f2f2f2);
  --color-bg-accent-secondary: #bbdbba;
  --color-bg-accent-secondary: light-dark(#bbdbba, #156d12);
  --color-bg-accent-secondary-hover: #9fcc9e;
  --color-bg-accent-secondary-hover: light-dark(#9fcc9e, #10530e);
  --color-bg-accent-tertiary: #d2e7d1;
  --color-bg-accent-tertiary: light-dark(#d2e7d1, #10530e);
  --color-bg-accent-quaternary: #e8f3e8;
  --color-bg-accent-quaternary: light-dark(#e8f3e8, #0c3d0a);
  --color-bg-error-primary: #c94a4a;
  --color-bg-error-primary: light-dark(#c94a4a, #762323);
  --color-bg-error-primary-hover: #b63636;
  --color-bg-error-primary-hover: light-dark(#b63636, #451717);
  --color-bg-utility-yellow-primary: #fffae1;
  --color-bg-utility-yellow-primary: light-dark(#fffae1, #461f01);
  --color-bg-utility-blue-primary: #e5f2ff;
  --color-bg-utility-blue-primary: light-dark(#e5f2ff, #22214f);
  /* Verified book author intro card (JAM-3265): light blue tint on web/apps;
   * dark mode uses the neutral tertiary surface + border, not utility blue. */
  --color-bg-verified-book-author-intro: #e5f2ff;
  --color-bg-verified-book-author-intro: light-dark(#e5f2ff, #171717);
  --color-border-verified-book-author-intro: transparent;
  --color-border-verified-book-author-intro: light-dark(transparent, #2b2b2b);
  --verified-book-author-intro-illustration-scale: 1;
  --color-fg-neutral-primary: #242424;
  --color-fg-neutral-primary: light-dark(#242424, #e5e5e5);
  --color-fg-neutral-primary-hover: #000000;
  --color-fg-neutral-primary-hover: light-dark(#000000, #ffffff);
  --color-fg-neutral-secondary: #6b6b6b;
  --color-fg-neutral-secondary: light-dark(#6b6b6b, #b3b3b3);
  --color-fg-neutral-secondary-hover: #3f3f3f;
  --color-fg-neutral-secondary-hover: light-dark(#3f3f3f, #d2d2d2);
  --color-fg-neutral-tertiary: #ffffff;
  --color-fg-neutral-tertiary: light-dark(#ffffff, #121212);
  --color-fg-accent-primary: #1a8917;
  --color-fg-accent-primary: light-dark(#1a8917, #6ab668);
  --color-fg-accent-primary-hover: #156d12;
  --color-fg-accent-primary-hover: light-dark(#156d12, #40993d);
  --color-fg-error-primary: #c94a4a;
  --color-fg-error-primary: light-dark(#c94a4a, #ce5a5a);
  --color-fg-error-primary-hover: #b63636;
  --color-fg-error-primary-hover: light-dark(#b63636, #c94a4a);
  --color-fg-utility-blue-primary: #437aff;
  --color-fg-utility-blue-primary: light-dark(#437aff, #3c9fff);
  /* The LinkedIn mark carries brand blue (`linkedinBlue` in `deprecatedColors.ts`) in light
   * mode only (JAM-3412): against any of the dark surfaces it only grazes the 3:1 non-text
   * floor, so dark mode keeps the grey10 the mark inherited from `--color-fg-neutral-primary`
   * before it had a color of its own. Move the two dark values together. */
  --color-fg-social-linkedin: #0a66c2;
  --color-fg-social-linkedin: light-dark(#0a66c2, #e5e5e5);
  --color-border-neutral-primary: #f2f2f2;
  --color-border-neutral-primary: light-dark(#f2f2f2, #3f3f3f);
  /* No consumer in Lite today — every `border.neutral.primary` call site reads `.base`.
   * Note the dark value is a step *darker* than the base above (grey83 against grey75), so
   * it loses contrast against the page rather than gaining it the way the light pair does.
   * Re-tone it before wiring this up to anything. */
  --color-border-neutral-primary-hover: #e5e5e5;
  --color-border-neutral-primary-hover: light-dark(#e5e5e5, #2b2b2b);
  --color-border-neutral-secondary: #242424;
  --color-border-neutral-secondary: light-dark(#242424, #d2d2d2);
  --color-border-neutral-secondary-hover: #000000;
  --color-border-neutral-secondary-hover: light-dark(#000000, #f9f9f9);
  --color-border-neutral-tertiary: #e5e5e5;
  --color-border-neutral-tertiary: light-dark(#e5e5e5, #3f3f3f);
  --color-border-neutral-tertiary-hover: #d2d2d2;
  --color-border-neutral-tertiary-hover: light-dark(#d2d2d2, #3f3f3f);
  --color-border-brand-primary: #191919;
  --color-border-brand-primary: light-dark(#191919, #ffffff);
  --color-border-accent-primary: #1a8917;
  --color-border-accent-primary: light-dark(#1a8917, #6ab668);
  --color-border-accent-primary-hover: #156d12;
  --color-border-accent-primary-hover: light-dark(#156d12, #40993d);
  --color-border-error-primary: #c94a4a;
  --color-border-error-primary: light-dark(#c94a4a, #762323);
  --color-border-error-primary-hover: #b63636;
  --color-border-error-primary-hover: light-dark(#b63636, #451717);
  --color-chart-accent-primary: #1a8917;
  --color-chart-accent-primary: light-dark(#1a8917, #84c082);
  --color-chart-accent-secondary: #9fcc9e;
  --color-chart-accent-secondary: light-dark(#9fcc9e, #1a8917);
  --color-chart-accent-tertiary: #bbdbba;
  --color-chart-accent-tertiary: light-dark(#bbdbba, #156d12);
  --color-chart-accent-quaternary: #e8f3e8;
  --color-chart-accent-quaternary: light-dark(#e8f3e8, #10530e);
  --color-chart-utility-yellow-primary: #fea010;
  --color-chart-utility-yellow-primary: light-dark(#fea010, #fea010);
  --color-chart-utility-yellow-secondary: #ffc017;
  --color-chart-utility-yellow-secondary: light-dark(#ffc017, #be5b04);
  --color-chart-utility-yellow-tertiary: #faedaf;
  --color-chart-utility-yellow-tertiary: light-dark(#faedaf, #be5b04);
  --color-chart-utility-yellow-tertiary: #fffae1;
  --color-chart-utility-yellow-tertiary: light-dark(#fffae1, #be5b04);
  /* Neutral now rides the grey scale and flips with the scheme, like the other chart tokens. */
  --color-chart-neutral-primary: #b3b3b3;
  --color-chart-neutral-primary: light-dark(#b3b3b3, #d2d2d2);
  --color-chart-neutral-secondary: #b3b3b3;
  --color-chart-neutral-secondary: light-dark(#b3b3b3, #d2d2d2);
  --color-chart-neutral-tertiary: #e5e5e5;
  --color-chart-neutral-tertiary: light-dark(#e5e5e5, #6b6b6b);

  /* The tint elevation shadows are drawn from — consumed only as a shadow color, by
   * `popoverShadow` (see `src/util/color.ts`), which layers it at two alphas.
   *
   * `transparent` in dark mode removes the shadow outright. Elevation there is carried by
   * `--color-bg-neutral-elevated` being a step lighter than the page, not by a cast shadow:
   * a dark page gives a shadow almost nothing to fall on, and any tint light enough to see
   * paints a halo *around* the surface instead of a shadow *under* it.
   *
   * Because this is a ``, `light-dark()` handles it and no cascade switch is needed:
   * it resolves per element, so a popover inside a light-pinned subtree (a landing page, a
   * `PinColorSchemeWrapper`) correctly keeps its shadow. */
  --color-shadow-elevated: #242424;
  --color-shadow-elevated: light-dark(#242424, transparent);

  /* Modal/dialog scrims. Must darken the page in both schemes — `neutral.primary`
   * matches the page background and disappears as an overlay. */
  --color-bg-scrim: #484848;
  --color-bg-scrim: light-dark(#484848, #000000);

  /* Submission status pills own their surface/text pairs rather than reusing
   * `--color-bg-utility-*`. Those utility surfaces are shared with decorative
   * callouts that carry no text, so re-toning one for a callout silently broke
   * the contrast of every pill drawn on it (JAM-3268). Keep each pair together
   * and change them together. */
  --color-status-in-review-background: #e5f2ff;
  --color-status-in-review-background: light-dark(#e5f2ff, #22214f);
  --color-status-in-review-text: #437aff;
  --color-status-in-review-text: light-dark(#437aff, #6ab7ff);
  --color-status-edits-requested-background: #fffae1;
  --color-status-edits-requested-background: light-dark(#fffae1, #461f01);
  --color-status-edits-requested-text: #be5b04;
  --color-status-edits-requested-text: light-dark(#be5b04, #fea010);

  /* Custom Story Footer color palette */
  --color-story-footer-bg-subtle: #f7f4ed;
  --color-story-footer-bg-subtle: light-dark(#f7f4ed, #242424);
  --color-story-footer-bg-contrast: #242424;
  --color-story-footer-bg-contrast: light-dark(#242424, #dacfbe);
  --color-story-footer-fg-subtle: #242424;
  --color-story-footer-fg-subtle: light-dark(#242424, #d2d2d2);
  --color-story-footer-fg-contrast: #ffffff;
  --color-story-footer-fg-contrast: light-dark(#ffffff, #121212);
  --color-story-footer-placeholder-light-grey: #d2d2d2;
  --color-story-footer-placeholder-light-grey: light-dark(#d2d2d2, #242424);
  --color-story-footer-placeholder-dark-grey: #6b6b6b;
  --color-story-footer-placeholder-dark-grey: light-dark(#6b6b6b, #3f3f3f);
}

@media (prefers-color-scheme: dark) {
  :root {
    --invert-in-dark-mode: 1;
    --blend-in-dark-mode: screen;
  }
}

html[data-color-scheme='light'] {
  color-scheme: light;
  --invert-in-dark-mode: 0;
  --blend-in-dark-mode: normal;
}

html[data-color-scheme='dark'] {
  color-scheme: dark;
  --invert-in-dark-mode: 1;
  --blend-in-dark-mode: screen;
}

@media print {
  :root,
  html[data-color-scheme='dark'] {
    color-scheme: light !important;
    --invert-in-dark-mode: 0;
    --blend-in-dark-mode: normal;
  }

  [data-color-scheme] {
    color-scheme: light !important;
  }
}

:root {
  --m2-fg-lightest: light-dark(rgba(0, 0, 0, 0.05), rgba(255, 255, 255, 0.05));
  --m2-fg-lighter: light-dark(rgba(0, 0, 0, 0.15), rgba(255, 255, 255, 0.15));
  --m2-fg-light: light-dark(rgba(0, 0, 0, 0.3), rgba(255, 255, 255, 0.3));
  --m2-fg-normal: light-dark(rgba(0, 0, 0, 0.54), rgba(255, 255, 255, 0.54));
  --m2-fg-dark: light-dark(rgba(0, 0, 0, 0.68), rgba(255, 255, 255, 0.68));
  --m2-fg-subtle: light-dark(rgba(0, 0, 0, 0.76), rgba(255, 255, 255, 0.76));
  --m2-fg-darker: light-dark(rgba(0, 0, 0, 0.84), rgba(255, 255, 255, 0.84));
  --m2-fg-darkest: light-dark(rgba(0, 0, 0, 0.9), rgba(255, 255, 255, 0.9));
  --m2-fg-black: light-dark(#000000, #ffffff);
  --m2-fg-body: var(--m2-fg-darker);
  --m2-bg-overlay: light-dark(rgba(255, 255, 255, 0.97), rgba(23, 23, 23, 0.97));
  --m2-bg-overlay-light: light-dark(rgba(255, 255, 255, 0.65), rgba(23, 23, 23, 0.65));
  --m2-border-card: light-dark(rgba(0, 0, 0, 0.04), rgba(255, 255, 255, 0.04));
  --m2-border-card-elevated: light-dark(rgba(0, 0, 0, 0.04), transparent);
  --m2-shadow-elevated-in-page: light-dark(rgba(0, 0, 0, 0.05), transparent);
  --m2-shadow-elevated-cover: light-dark(rgba(0, 0, 0, 0.08), transparent);
  --m2-shadow-subtle: light-dark(rgba(0, 0, 0, 0.03), transparent);
  --m2-border-card-inset: light-dark(rgba(0, 0, 0, 0.09), rgba(255, 255, 255, 0.09));
  --m2-border-postPreview: light-dark(rgba(0, 0, 0, 0.1), rgba(255, 255, 255, 0.1));
  --m2-border-publication-nav: light-dark(rgba(0, 0, 0, 0.1), rgba(255, 255, 255, 0.1));
  --m2-border-browsable: light-dark(rgba(0, 0, 0, 0.0785), rgba(255, 255, 255, 0.0785));
  --m2-border-popover: light-dark(rgba(0, 0, 0, 0.0785), transparent);
  --m2-border-popover-heading: light-dark(rgba(0, 0, 0, 0.05), rgba(255, 255, 255, 0.1));
  --m2-shadow-popover-blur: light-dark(0 1px 2px rgba(0, 0, 0, 0.25), none);
  --m2-shadow-popover-ring: light-dark(0 0 1px rgba(0, 0, 0, 0.35), none);
  --m2-shadow-popover-safari-blur: light-dark(0 1px 1px 1px rgba(0, 0, 0, 0.05), none);
  --m2-shadow-popover-safari-ring: light-dark(0 0 1px 1px rgba(0, 0, 0, 0.15), none);
  --m2-shadow-popover-arrow: light-dark(rgba(0, 0, 0, 0.84), transparent);
  --m2-shadow-popover-arrow-normal: light-dark(rgba(0, 0, 0, 0.54), transparent);
  --m2-bg-gray-lightest: light-dark(rgb(250, 250, 250), #1f1f1f);
  --m2-bg-gray-lighter: light-dark(rgb(245, 245, 245), #1f1f1f);
  --m2-bg-gray-light: light-dark(rgb(240, 240, 240), #242424);
  --m2-bg-variants-expired: light-dark(rgb(247, 201, 209), #762323);
  --m2-bg-table-danger: light-dark(#f2dede, #762323);
  --m2-bg-table-danger-hover: light-dark(#ebcccc, #8f3a3a);
  --m2-bg-brand-sky: light-dark(#e2eff8, transparent);
  --m2-bg-design-system-page: light-dark(#f9f9f9, #171717);
  --m2-bg-brand: light-dark(rgba(0, 0, 0, 0.84), #ffffff);
  --m2-bg-brand-hover: light-dark(rgba(0, 0, 0, 0.9), #f2f2f2);
  --m2-fg-on-brand: light-dark(rgba(255, 255, 255, 0.97), #171717);
  --m2-bg-brand-hover-legacy: light-dark(#000000, #f2f2f2);
  --m2-fg-placeholder: light-dark(rgb(179, 179, 177), rgba(255, 255, 255, 0.3));
  --m2-fill-error-icon: light-dark(rgba(0, 0, 0, 0.15), #3f3f3f);
}
}
